module asyn_fifo #(
    parameter DEPTH = 16,
    parameter WIDTH = 8,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);


function [3:0] bin_to_gray(input [3:0] bin);
    begin
        bin_to_gray = {bin[3], bin[3] ^ bin[2], bin[2] ^ bin[1], bin[1] ^ bin[0]};
    end
endfunction

function [3:0] gray_to_bin(input [3:0] gray);
    begin
        gray_to_bin[3] = gray[3];
        gray_to_bin[2] = gray[3] ^ gray[2];
        gray_to_bin[1] = gray[3] ^ gray[2] ^ gray[1];
        gray_to_bin[0] = gray[3] ^ gray[2] ^ gray[1] ^ gray[0];
    end
endfunction

reg [3:0] waddr_bin;
reg [3:0] wptr;
reg [3:0] wptr_buff;
reg [3:0] wptr_syn;
reg [3:0] raddr_bin;
reg [3:0] rptr;
reg [3:0] rptr_buff;
reg [3:0] rptr_syn;

dual_port_RAM #(DEPTH, WIDTH) ram_inst (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(waddr_bin[$clog2(DEPTH)-1:0]),
    .wdata(wdata),
    .renc(rinc && !rempty),
    .raddr(raddr_bin[$clog2(DEPTH)-1:0]),
    .rdata(rdata)
);

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 4'd0;
        wptr <= 4'd0;
        wptr_buff <= 4'd0;
    end else begin
        if (winc && !wfull) begin
            waddr_bin <= waddr_bin + 1;
            wptr <= bin_to_gray(waddr_bin);
        end
        wptr_buff <= wptr;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 4'd0;
        rptr <= 4'd0;
        rptr_buff <= 4'd0;
    end else begin
        if (rinc && !rempty) begin
            raddr_bin <= raddr_bin + 1;
            rptr <= bin_to_gray(raddr_bin);
        end
        rptr_buff <= rptr;
    end
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_syn <= 4'd0;
    end else begin
        rptr_syn <= rptr_buff;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_syn <= 4'd0;
    end else begin
        wptr_syn <= wptr_buff;
    end
end

assign wfull = (wptr == {~rptr_syn[$clog2(DEPTH)], rptr_syn[$clog2(DEPTH)-1:0]});
assign rempty = (rptr == wptr_syn);
endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
